68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    /**
74	     * Dedicated audit logger. A successful owner create emits a single line here carrying the new
75	     * owner's id, customer code, registration date and membership level, so the create side-effect
76	     * can be audited independently of the application log.
77	     */
78	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
79	
80	    private final ClinicService clinicService;
81	
82	    private final OwnerMapper ownerMapper;
83	
84	    private final PetMapper petMapper;
85	
86	    private final VisitMapper visitMapper;
87	
88	    /**
89	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
90	     * and a domain containing at least one dot, with no whitespace in any segment.
91	     */
92	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
93	
94	    /**
95	     * Required national-number length per E.164 country code. A normalized telephone whose country
96	     * code appears here must carry exactly this many national digits after the code; Australia
97	     * ({@code +61}) requires 9 and the North American Numbering Plan ({@code +1}) requires 10.
98	     * Country codes not listed are only subject to the generic 8-to-15 total-digit rule.
99	     */
100	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTH = Map.of("61", 9, "1", 10);
101	
102	    /**
103	     * Maximum number of owners permitted in a single city. A create whose city already holds this many
104	     * owners (compared case-insensitively) is rejected with a 409 Conflict.
105	     */
106	    private static final int MAX_OWNERS_PER_CITY = 50;
107	
108	    /**
109	     * Maximum number of owners that may be registered on a single day (by registration date). A create
110	     * attempted once this many owners already carry today's registration date is rejected with a
111	     * 429 Too Many Requests.
112	     */
113	    private static final int MAX_OWNERS_PER_DAY = 100;
114	
115	    /**
116	     * Threshold above which a create is flagged with a bulk-signup warning. When more than this many
117	     * owners already carry the new owner's registration date, the created owner is flagged
118	     * ({@code bulkSignupWarning} true); otherwise the flag is false.
119	     */
120	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
121	
122	    /**
123	     * Expansions of the common street-type abbreviations recognised by {@link #normalizeAddress}.
124	     * Keys and values are upper-case, matching the casing the address is folded to before expansion.
125	     */
126	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
127	        "ST", "STREET",
128	        "RD", "ROAD",
129	        "AVE", "AVENUE");
130	
131	    public OwnerRestControllerV1(ClinicService clinicService,
132	                                 OwnerMapper ownerMapper,
133	                                 PetMapper petMapper,
134	                                 VisitMapper visitMapper) {
135	        this.clinicService = clinicService;
136	        this.ownerMapper = ownerMapper;
137	        this.petMapper = petMapper;
138	        this.visitMapper = visitMapper;
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
144	        Collection<Owner> owners;
145	        if (lastName != null) {
146	            owners = this.clinicService.findOwnerByLastName(lastName);
147	        } else {
148	            owners = this.clinicService.findAllOwners();
149	        }
150	        if (owners.isEmpty()) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Override
158	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
159	        Owner owner = this.clinicService.findOwnerById(ownerId);
160	        if (owner == null) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
162	        }
163	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Override
168	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
169	        validateRequiredFields(ownerFieldsDto);
170	        HttpHeaders headers = new HttpHeaders();
171	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
172	        LocalDate registrationDate = Owner.resolveRegistrationDate(owner.getRegistrationDate());
173	        owner.setRegistrationDate(registrationDate);
174	        requireDailyCapacity(registrationDate);
175	        requireCityHasCapacity(owner.getCity());
176	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
177	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
178	            joinHousehold(owner);
179	        } else {
180	            requireUniqueHousehold(owner.getLastName(), owner.getAddress());
181	        }
182	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
183	        requireUniqueTelephone(telephone);
184	        owner.setTelephone(telephone);
185	        String email = normalizeEmail(ownerFieldsDto.getEmail());
186	        requireUniqueEmail(email);
187	        owner.setEmail(email);
188	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
189	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
190	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
191	        this.clinicService.saveOwner(owner);
192	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
193	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
194	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
195	        headers.setLocation(UriComponentsBuilder.newInstance()
196	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
197	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
198	    }
199	
200	    /**
201	     * Rejects a create once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the new owner's
202	     * adjusted business-day registration date. Existing owners are counted by {@code registrationDate}
203	     * equal to that date, before the new owner is saved, so the count reflects only the owners that
204	     * existed prior to this create.
205	     *
206	     * @param registrationDate the new owner's effective registration date, already rolled forward onto
207	     *     a business day
208	     * @throws DailyOwnerLimitException if {@value #MAX_OWNERS_PER_DAY} or more owners are already
209	     *     registered on that business day
210	     */
211	    private void requireDailyCapacity(LocalDate registrationDate) {
212	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
213	            throw new DailyOwnerLimitException(registrationDate);
214	        }
215	    }
216	
217	    /**
218	     * Counts the existing owners whose registration date equals the given business-day date. This is
219	     * evaluated before the new owner is saved, so it reflects only the owners that existed prior to
220	     * this create. It is the single definition of the per-day count shared by the daily-limit rule and
221	     * the bulk-signup warning.
222	     *
223	     * @param registrationDate the effective business-day registration date to count against
224	     * @return the number of pre-existing owners registered on that date
225	     */
226	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
227	        return this.clinicService.findAllOwners().stream()
228	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
229	            .count();
230	    }
231	
232	    /**
233	     * Rejects an owner whose city already contains the maximum allowed number of owners
234	     * ({@value #MAX_OWNERS_PER_CITY}). Existing owners are counted by city compared case-insensitively,
235	     * before the new owner is saved, so the count reflects only the owners that existed prior to this
236	     * create.
237	     *
238	     * @param city the city of the owner being created
239	     * @throws CityOwnerLimitException if the city already holds {@value #MAX_OWNERS_PER_CITY} or more owners
240	     */
241	    private void requireCityHasCapacity(String city) {
242	        long cityOwnerCount = this.clinicService.findAllOwners().stream()
243	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
244	            .count();
245	        if (cityOwnerCount >= MAX_OWNERS_PER_CITY) {
246	            throw new CityOwnerLimitException(city);
247	        }
248	    }
249	
250	    /**
251	     * Generates the customer code for a newly created owner, formatted
252	     * {@code '<CITY3>-<LAST3>-<NNNN>'}. {@code CITY3} is the upper-cased first three letters of the
253	     * city, {@code LAST3} the upper-cased first three letters of the last name, and {@code NNNN} a
254	     * per-city, 4-digit zero-padded sequence equal to one more than the number of owners already in
255	     * that city (e.g. {@code 'LON-SMI-0007'}).
256	     *
257	     * @param city the owner's city
258	     * @param lastName the owner's last name
259	     * @return the generated customer code
260	     */
261	    private String generateCustomerCode(String city, String lastName) {
262	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
263	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
264	        int sequence = (int) this.clinicService.findAllOwners().stream()
265	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
266	            .count() + 1;
267	        return String.format("%s-%s-%04d", city3, last3, sequence);
268	    }
269	
270	    /**
271	     * Counts the existing owners that already share the given first name and last name, compared
272	     * case-insensitively. This is evaluated before the new owner is saved, so it reflects only the
273	     * owners that existed prior to this create.
274	     *
275	     * @param firstName the first name of the owner being created
276	     * @param lastName the last name of the owner being created
277	     * @return the number of pre-existing namesakes
278	     */
279	    private int countNamesakes(String firstName, String lastName) {
280	        return (int) this.clinicService.findAllOwners().stream()
281	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
282	                && equalsIgnoreCase(existing.getLastName(), lastName))
283	            .count();
284	    }
285	
286	    /**
287	     * Compares two possibly-{@code null} strings for equality, ignoring case. Two {@code null} values
288	     * are considered equal and a {@code null} is never equal to a non-{@code null} value.
289	     *
290	     * @param a the first value, possibly {@code null}
291	     * @param b the second value, possibly {@code null}
292	     * @return whether the values are equal ignoring case
293	     */
294	    private boolean equalsIgnoreCase(String a, String b) {
295	        return a == null ? b == null : a.equalsIgnoreCase(b);
296	    }
297	
298	    /**
299	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
300	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
301	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
302	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
303	     *
304	     * @param ownerFieldsDto the submitted owner fields
305	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
306	     */
307	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
308	        List<String> invalidFields = new ArrayList<>();
309	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
310	            invalidFields.add("firstName");
311	        }
312	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
313	            invalidFields.add("lastName");
314	        }
315	        if (!StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddress()))) {
316	            invalidFields.add("address");
317	        }
318	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
319	            invalidFields.add("city");
320	        }
321	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
322	            invalidFields.add("telephone");
323	        }
324	        if (!invalidFields.isEmpty()) {
325	            throw new InvalidOwnerFieldsException(invalidFields);
326	        }
327	    }
328	
329	    /**
330	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
331	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
332	     * what gets stored and returned.
333	     *
334	     * @param telephone the raw telephone value from the request
335	     * @return the normalized E.164 telephone number
336	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
337	     */
338	    private String normalizeTelephone(String telephone) {
339	        String e164 = toE164(telephone);
340	        if (e164 == null) {
341	            throw new InvalidOwnerFieldsException(List.of("telephone"));
342	        }
343	        return e164;
344	    }
345	
346	    /**
347	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
348	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
349	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
350	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
351	     * it contains 8 to 15 digits after the {@code '+'} and, for a recognized country code (see
352	     * {@link #NATIONAL_NUMBER_LENGTH}), carries exactly that country's required national-number length.
353	     *
354	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
355	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
356	     *
357	     * @param telephone the raw telephone value, possibly {@code null}
358	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
359	     */
360	    private String toE164(String telephone) {
361	        if (telephone == null) {
362	            return null;
363	        }
364	        String cleaned = telephone.replaceAll("[ \\-()]", "");
365	        String digits;
366	        if (cleaned.startsWith("+")) {
367	            digits = cleaned.substring(1);
368	        } else {
369	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
370	            digits = "61" + national;
371	        }
372	        if (!digits.matches("[0-9]{8,15}")) {
373	            return null;
374	        }
375	        if (!nationalNumberLengthValid(digits)) {
376	            return null;
377	        }
378	        return "+" + digits;
379	    }
380	
381	    /**
382	     * Checks a normalized E.164 digit string (country code followed by national digits, without the
383	     * leading {@code '+'}) against the per-country national-number length rule. For a country code
384	     * listed in {@link #NATIONAL_NUMBER_LENGTH} the national part must have exactly the required length
385	     * (e.g. {@code '+61'} needs 9 national digits, {@code '+1'} needs 10); any other country code is
386	     * accepted, leaving only the generic total-length rule to apply.
387	     *
388	     * @param digits the E.164 digits without the leading {@code '+'}
389	     * @return {@code true} if the national-number length matches the country code's requirement
390	     */
391	    private boolean nationalNumberLengthValid(String digits) {
392	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTH.entrySet()) {
393	            String code = entry.getKey();
394	            if (digits.startsWith(code)) {
395	                return digits.length() - code.length() == entry.getValue();
396	            }
397	        }
398	        return true;
399	    }
400	
401	    /**
402	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
403	     * {@code null}. When present, the value must be a syntactically valid address; it is then stored
404	     * and returned lower-cased.
405	     *
406	     * @param email the raw email value from the request, possibly {@code null}
407	     * @return the lower-cased email, or {@code null} when none was supplied
408	     * @throws InvalidOwnerFieldsException if a value is present but not a valid email address
409	     */
410	    private String normalizeEmail(String email) {
411	        if (!StringUtils.hasText(email)) {
412	            return null;
413	        }
414	        String trimmed = email.trim();
415	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
416	            throw new InvalidOwnerFieldsException(List.of("email"));
417	        }
418	        return trimmed.toLowerCase(Locale.ROOT);
419	    }
420	
421	    /**
422	     * Rejects a telephone number whose E.164 form is already used by an existing owner. This enforces
423	     * that no two owners share the same E.164 telephone. Existing values are compared by their E.164
424	     * form; a stored value that cannot form a valid E.164 number is compared as-is.
425	     *
426	     * @param telephone the normalized (E.164) telephone of the owner being created
427	     * @throws DuplicateTelephoneException if another owner already has this E.164 telephone
428	     */
429	    private void requireUniqueTelephone(String telephone) {
430	        boolean inUse = this.clinicService.findAllOwners().stream()
431	            .map(Owner::getTelephone)
432	            .filter(existing -> existing != null)
433	            .map(existing -> {
434	                String e164 = toE164(existing);
435	                return e164 != null ? e164 : existing;
436	            })
437	            .anyMatch(telephone::equals);
438	        if (inUse) {
439	            throw new DuplicateTelephoneException(telephone);
440	        }
441	    }
442	
443	    /**
444	     * Rejects an owner whose email, compared by its lower-cased form, is already used by an existing
445	     * owner. This enforces that no two owners share the same email case-insensitively. An absent
446	     * ({@code null}) email is always allowed, since no email is being claimed. Existing values are
447	     * compared by their lower-cased form, so a stored value in any casing is matched.
448	     *
449	     * @param email the normalized (lower-cased) email of the owner being created, or {@code null}
450	     * @throws DuplicateEmailException if another owner already has this email (compared lower-cased)
451	     */
452	    private void requireUniqueEmail(String email) {
453	        if (email == null) {
454	            return;
455	        }
456	        boolean inUse = this.clinicService.findAllOwners().stream()
457	            .map(Owner::getEmail)
458	            .filter(existing -> existing != null)
459	            .anyMatch(existing -> existing.toLowerCase(Locale.ROOT).equals(email));
460	        if (inUse) {
461	            throw new DuplicateEmailException(email);
462	        }
463	    }
464	
465	    /**
466	     * Rejects an owner whose last name and address match those of an existing owner, where both are
467	     * compared case-insensitively and with runs of whitespace collapsed to a single space (a shared
468	     * household). The caller skips this check when the request opts in via {@code sharesHousehold}.
469	     *
470	     * @param lastName the last name of the owner being created
471	     * @param address the address of the owner being created
472	     * @throws DuplicateHouseholdException if another owner shares the same last name and address
473	     */
474	    private void requireUniqueHousehold(String lastName, String address) {
475	        if (!findHouseholdMembers(lastName, address).isEmpty()) {
476	            throw new DuplicateHouseholdException(lastName, address);
477	        }
478	    }
479	
480	    /**
481	     * Returns the existing owners that belong to the same household as the given last name and
482	     * address, i.e. those whose last name and address match case-insensitively and with runs of
483	     * whitespace collapsed to a single space.
484	     *
485	     * @param lastName the last name to match
486	     * @param address the address to match
487	     * @return the matching owners (possibly empty, never {@code null})
488	     */
489	    private List<Owner> findHouseholdMembers(String lastName, String address) {
490	        String normalizedLastName = normalizeForHousehold(lastName);
491	        String normalizedAddress = normalizeAddress(address);
492	        return this.clinicService.findAllOwners().stream()
493	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
494	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
495	            .toList();
496	    }
497	
498	    /**
499	     * Joins the owner being created to the shared household of any existing owner(s) that have the
500	     * same last name and address (compared case-insensitively with collapsed whitespace). Every
501	     * member of the household - the existing owners and the new one - is assigned the same stable
502	     * {@code householdId}, so the shared identifier can be read back from any of them.
503	     *
504	     * <p>When no existing owner shares the household there is nobody to share an identifier with, so
505	     * the owner is left without a {@code householdId}.
506	     *
507	     * <p>Every member of the household - the existing owners and the new one - is also stamped with
508	     * the household's member count after this create ({@code householdSize}), so the shared size can
509	     * be read back from any of them.
510	     *
511	     * @param owner the owner being created, whose {@code householdId} is set when a household is joined
512	     */
513	    private void joinHousehold(Owner owner) {
514	        List<Owner> members = findHouseholdMembers(owner.getLastName(), owner.getAddress());
515	        if (members.isEmpty()) {
516	            return;
517	        }
518	        String householdId = computeHouseholdId(owner.getLastName(), owner.getAddress());
519	        int householdSize = members.size() + 1;
520	        owner.setHouseholdId(householdId);
521	        owner.setHouseholdSize(householdSize);
522	        for (Owner member : members) {
523	            member.setHouseholdId(householdId);
524	            member.setHouseholdSize(householdSize);
525	            this.clinicService.saveOwner(member);
526	        }
527	    }
528	
529	    /**
530	     * Computes the stable, shared household identifier for a last name and address. The value is
531	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last
532	     * name and address, so every owner in the same household computes the same identifier.
533	     *
534	     * @param lastName the last name of the household
535	     * @param address the address of the household
536	     * @return the household identifier, formatted {@code 'HH-<12 upper-case hex digits>'}
537	     */
538	    private String computeHouseholdId(String lastName, String address) {
539	        String key = normalizeForHousehold(lastName) + "\n" + normalizeAddress(address);
540	        try {
541	            byte[] digest = MessageDigest.getInstance("SHA-256")
542	                .digest(key.getBytes(StandardCharsets.UTF_8));
543	            StringBuilder hex = new StringBuilder();
544	            for (int i = 0; i < 6; i++) {
545	                hex.append(String.format("%02X", digest[i]));
546	            }
547	            return "HH-" + hex;
548	        } catch (NoSuchAlgorithmException e) {
549	            throw new IllegalStateException("SHA-256 algorithm not available", e);
550	        }
551	    }
552	
553	    /**
554	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
555	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
556	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
557	     *
558	     * @param value the raw value, possibly {@code null}
559	     * @return the normalized value
560	     */
561	    private String normalizeForHousehold(String value) {
562	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
563	    }
564	
565	    /**
566	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
567	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
568	     * value yields an empty string.
569	     *
570	     * @param value the raw value, possibly {@code null}
571	     * @return the trimmed, whitespace-collapsed value
572	     */
573	    private String collapseWhitespace(String value) {
574	        if (value == null) {
575	            return "";
576	        }
577	        return value.trim().replaceAll("\\s+", " ");
578	    }
579	
580	    /**
581	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
582	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
583	     * is upper-cased, and common street-type abbreviations are expanded as whole words
584	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
585	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
586	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
587	     *
588	     * @param address the raw address value, possibly {@code null}
589	     * @return the normalized address
590	     */
591	    private String normalizeAddress(String address) {
592	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
593	        if (collapsed.isEmpty()) {
594	            return "";
595	        }
596	        String[] tokens = collapsed.split(" ");
597	        StringBuilder normalized = new StringBuilder();
598	        for (int i = 0; i < tokens.length; i++) {
599	            if (i > 0) {
600	                normalized.append(' ');
601	            }
602	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
603	        }
604	        return normalized.toString();
605	    }
606	
607	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
608	    @Override
609	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
610	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
611	        if (currentOwner == null) {
612	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
613	        }
614	        currentOwner.setAddress(ownerFieldsDto.getAddress());
615	        currentOwner.setCity(ownerFieldsDto.getCity());
616	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
617	        currentOwner.setLastName(ownerFieldsDto.getLastName());
618	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
619	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
620	        this.clinicService.saveOwner(currentOwner);
621	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
622	    }
623	
624	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
625	    @Transactional
626	    @Override
627	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
628	        Owner owner = this.clinicService.findOwnerById(ownerId);
629	        if (owner == null) {
630	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
631	        }
632	        this.clinicService.deleteOwner(owner);
633	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
634	    }
635	
636	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
637	    @Override
638	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
639	        Owner owner = this.clinicService.findOwnerById(ownerId);
640	        if (owner == null) {
641	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
642	        }
643	        HttpHeaders headers = new HttpHeaders();
644	        Pet pet = petMapper.toPet(petFieldsDto);
645	        owner.setId(ownerId);
646	        pet.setOwner(owner);
647	        pet.getType().setName(null);
648	        this.clinicService.savePet(pet);
649	        PetDto petDto = petMapper.toPetDto(pet);
650	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
651	            .buildAndExpand(pet.getId()).toUri());
652	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
653	    }
654	
655	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
656	    @Override
657	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
658	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
659	        if (currentOwner != null) {
660	            Pet currentPet = this.clinicService.findPetById(petId);
661	            if (currentPet != null) {
662	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
663	                currentPet.setName(petFieldsDto.getName());
664	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
665	                this.clinicService.savePet(currentPet);
666	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
667	            }
668	        }
669	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
670	    }
671	
672	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
673	    @Override
674	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
675	        HttpHeaders headers = new HttpHeaders();
676	        Visit visit = visitMapper.toVisit(visitFieldsDto);
677	        Pet pet = new Pet();
678	        pet.setId(petId);
679	        visit.setPet(pet);
680	        this.clinicService.saveVisit(visit);
681	        VisitDto visitDto = visitMapper.toVisitDto(visit);
682	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
683	            .buildAndExpand(visit.getId()).toUri());
684	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
685	    }
686	
687	
688	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
689	    @Override
690	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
691	        Owner owner = this.clinicService.findOwnerById(ownerId);
692	        if (owner != null) {
693	            Pet pet = owner.getPet(petId);
694	            if (pet != null) {
695	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
696	            }
697	        }
698	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
699	    }
700	}
