16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (a '+' followed by 8 to 15 digits)")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date", columnDefinition = "DATE")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @Column(name = "household_size")
67	    private Integer householdSize;
68	
69	    @Column(name = "bulk_signup_warning")
70	    private Boolean bulkSignupWarning;
71	
72	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
73	    private Set<Pet> pets;
74	
75	    /**
76	     * Fixed city-to-region table used to derive {@link #getLocality() locality}. Any city not
77	     * listed derives the locality {@code 'UNKNOWN'}.
78	     */
79	    private static final Map<String, String> CITY_REGION = Map.of(
80	        "Sydney", "NSW",
81	        "Melbourne", "VIC",
82	        "Brisbane", "QLD");
83	
84	    public String getAddress() {
85	        return this.address;
86	    }
87	
88	    public void setAddress(String address) {
89	        this.address = address;
90	    }
91	
92	    public String getCity() {
93	        return this.city;
94	    }
95	
96	    public void setCity(String city) {
97	        this.city = city;
98	    }
99	
100	    public String getTelephone() {
101	        return this.telephone;
102	    }
103	
104	    public void setTelephone(String telephone) {
105	        this.telephone = telephone;
106	    }
107	
108	    public String getEmail() {
109	        return this.email;
110	    }
111	
112	    public void setEmail(String email) {
113	        this.email = email;
114	    }
115	
116	    public LocalDate getRegistrationDate() {
117	        return this.registrationDate;
118	    }
119	
120	    public void setRegistrationDate(LocalDate registrationDate) {
121	        this.registrationDate = registrationDate;
122	    }
123	
124	    public String getCustomerCode() {
125	        return this.customerCode;
126	    }
127	
128	    public void setCustomerCode(String customerCode) {
129	        this.customerCode = customerCode;
130	    }
131	
132	    /**
133	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
134	     * the last two digits of the registration date's year (e.g. {@code 'LON-SMI-0007-M26'}). Derived
135	     * from the owner's own customer code and registration date; {@code null} when either is absent.
136	     *
137	     * @return the membership number, or {@code null} when it cannot be derived
138	     */
139	    public String getMembershipNumber() {
140	        if (this.customerCode == null || this.registrationDate == null) {
141	            return null;
142	        }
143	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
144	    }
145	
146	    /**
147	     * The owner's numeric membership level, derived from the values frozen at create time. It starts
148	     * at 1, gains 1 when an email address is present, gains 1 when the owner has no namesakes
149	     * ({@code namesakeCount} is 0), and is capped at 3. Level 4 is reserved for tenure.
150	     *
151	     * @return the membership level, an integer from 1 to 3
152	     */
153	    public Integer getMembershipLevel() {
154	        int level = 1;
155	        boolean hasEmail = this.email != null && !this.email.isBlank();
156	        if (hasEmail) {
157	            level++;
158	        }
159	        boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
160	        if (hasNoNamesakes) {
161	            level++;
162	        }
163	        return Math.min(level, 3);
164	    }
165	
166	    /**
167	     * The owner's locality, derived from the {@link #getCity() city} using the fixed
168	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD). Returns the canonical
169	     * region string, or {@code 'UNKNOWN'} when the city is absent or not in the table.
170	     *
171	     * @return the canonical region string, or {@code 'UNKNOWN'}
172	     */
173	    public String getLocality() {
174	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
175	    }
176	
177	    /**
178	     * The owner's preferred contact channel, derived from the owner's details. Returns
179	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
180	     *
181	     * @return {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}
182	     */
183	    public String getContactPreference() {
184	        boolean hasEmail = this.email != null && !this.email.isBlank();
185	        return hasEmail ? "EMAIL" : "PHONE";
186	    }
187	
188	    public String getHouseholdId() {
189	        return this.householdId;
190	    }
191	
192	    public void setHouseholdId(String householdId) {
193	        this.householdId = householdId;
194	    }
195	
196	    public Integer getNamesakeCount() {
197	        return this.namesakeCount;
198	    }
199	
200	    public void setNamesakeCount(Integer namesakeCount) {
201	        this.namesakeCount = namesakeCount;
202	    }
203	
204	    public Integer getHouseholdSize() {
205	        return this.householdSize;
206	    }
207	
208	    public void setHouseholdSize(Integer householdSize) {
209	        this.householdSize = householdSize;
210	    }
211	
212	    public Boolean getBulkSignupWarning() {
213	        return this.bulkSignupWarning;
214	    }
215	
216	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
217	        this.bulkSignupWarning = bulkSignupWarning;
218	    }
219	
220	    /**
221	     * Stamps the effective registration date exactly once on insert, so every newly persisted owner
222	     * carries a resolved, business-day registration date (see {@link #resolveRegistrationDate}).
223	     */
224	    @PrePersist
225	    void onCreate() {
226	        this.registrationDate = resolveRegistrationDate(this.registrationDate);
227	    }
228	
229	    /**
230	     * Resolves the effective registration date and rolls it onto a business day. An absent
231	     * ({@code null}) value defaults to the server's current date; a supplied value is used as-is.
232	     * The resulting date is then rolled forward so it never falls on a weekend: a Saturday or Sunday
233	     * becomes the following Monday, while any weekday is returned unchanged.
234	     *
235	     * <p>This is the single definition of both the defaulting and the business-day roll, used
236	     * wherever the effective registration date is needed - by the {@code @PrePersist} hook that
237	     * stamps the owner and by the create endpoint that counts owners per business day.
238	     *
239	     * @param supplied the registration date from the request, or {@code null} when none was supplied
240	     * @return the effective registration date, guaranteed to fall on a business day
241	     */
242	    public static LocalDate resolveRegistrationDate(LocalDate supplied) {
243	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
244	        return switch (effective.getDayOfWeek()) {
245	            case SATURDAY -> effective.plusDays(2);
246	            case SUNDAY -> effective.plusDays(1);
247	            default -> effective;
248	        };
249	    }
250	
251	    protected Set<Pet> getPetsInternal() {
252	        if (this.pets == null) {
253	            this.pets = new HashSet<>();
254	        }
255	        return this.pets;
256	    }
257	
258	    protected void setPetsInternal(Set<Pet> pets) {
259	        this.pets = pets;
260	    }
261	
262	    public List<Pet> getPets() {
263	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
264	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
265	        return Collections.unmodifiableList(sortedPets);
266	    }
267	
268	    public void setPets(List<Pet> pets) {
269	        this.pets = new HashSet<>(pets);
270	    }
271	
272	    public void addPet(Pet pet) {
273	        getPetsInternal().add(pet);
274	        pet.setOwner(this);
275	    }
276	
277	    /**
278	     * Return the Pet with the given name, or null if none found for this Owner.
279	     *
280	     * @param name to test
281	     * @return true if pet name is already in use
282	     */
283	    public Pet getPet(String name) {
284	        return getPet(name, false);
285	    }
286	
287	    /**
288	     * Return the Pet with the given name, or null if none found for this Owner.
289	     *
290	     * @param name to test
291	     * @return true if pet name is already in use
292	     */
293	    public Pet getPet(String name, boolean ignoreNew) {
294	        name = name.toLowerCase();
295	        for (Pet pet : getPetsInternal()) {
296	            if (!ignoreNew || !pet.isNew()) {
297	                String compName = pet.getName();
298	                compName = compName.toLowerCase();
299	                if (compName.equals(name)) {
300	                    return pet;
301	                }
302	            }
303	        }
304	        return null;
305	    }
306	
307	    public Pet getPet(Integer petId) {
308	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
309	    }
310	
311	    @Override
312	    public String toString() {
313	        return new ToStringCreator(this)
314	
315	            .append("id", this.getId())
316	            .append("new", this.isNew())
317	            .append("lastName", this.getLastName())
318	            .append("firstName", this.getFirstName())
319	            .append("address", this.address)
320	            .append("city", this.city)
321	            .append("telephone", this.telephone)
322	            .toString();
323	    }
324	}
